  const trimmed = imagePath.trim();
  if (!trimmed) return "";
  if (/^(https?:|data:)/i.test(trimmed)) return trimmed;
  const direct = app.vault.getAbstractFileByPath(trimmed);
  if (direct instanceof import_obsidian.TFile) return app.vault.getResourcePath(direct);
  const resolved = app.metadataCache.getFirstLinkpathDest(trimmed, "");
  if (resolved instanceof import_obsidian.TFile) return app.vault.getResourcePath(resolved);
